#!/usr/bin/env python3
"""A small persistent HTTP key-value service."""

from __future__ import annotations

import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import unquote_to_bytes, urlsplit


MAX_BODY = 1024 * 1024
KEY_PREFIX = "/v1/kv/"


class Store:
    def __init__(self, filename: str) -> None:
        self.path = Path(filename).resolve()
        self.lock = threading.RLock()
        self.entries: dict[str, dict[str, Any]] = {}
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            return
        try:
            with self.path.open("r", encoding="utf-8") as handle:
                raw = json.load(handle)
            if not isinstance(raw, dict) or raw.get("version") != 1:
                raise ValueError("unsupported data-file format")
            entries = raw.get("entries")
            if not isinstance(entries, dict):
                raise ValueError("invalid entries in data file")
            now = time.time()
            loaded: dict[str, dict[str, Any]] = {}
            for key, record in entries.items():
                if not isinstance(key, str) or not isinstance(record, dict) or "value" not in record:
                    raise ValueError("invalid entry in data file")
                expires = record.get("expires_at")
                if expires is not None:
                    if isinstance(expires, bool) or not isinstance(expires, (int, float)) or not math.isfinite(expires):
                        raise ValueError("invalid expiration in data file")
                    if expires <= now:
                        continue
                loaded[key] = {"value": record["value"], "expires_at": expires}
            self.entries = loaded
            if len(loaded) != len(entries):
                self._persist_locked()
        except (OSError, ValueError, TypeError, json.JSONDecodeError) as exc:
            raise RuntimeError(f"cannot load data file {self.path}: {exc}") from exc

    def _persist_locked(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        payload = {"version": 1, "entries": self.entries}
        temporary: str | None = None
        try:
            fd, temporary = tempfile.mkstemp(prefix=f".{self.path.name}.", dir=self.path.parent)
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                json.dump(payload, handle, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
                handle.write("\n")
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, self.path)
            temporary = None
            try:
                directory_fd = os.open(self.path.parent, os.O_RDONLY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
            except OSError:
                pass
        finally:
            if temporary is not None:
                try:
                    os.unlink(temporary)
                except FileNotFoundError:
                    pass

    def _purge_locked(self) -> bool:
        now = time.time()
        expired = [key for key, record in self.entries.items()
                   if record["expires_at"] is not None and record["expires_at"] <= now]
        for key in expired:
            del self.entries[key]
        if expired:
            self._persist_locked()
        return bool(expired)

    def put(self, key: str, value: Any, ttl: float | None) -> bool:
        with self.lock:
            self._purge_locked()
            created = key not in self.entries
            expires = None if ttl is None else time.time() + ttl
            old = self.entries.get(key)
            self.entries[key] = {"value": value, "expires_at": expires}
            try:
                self._persist_locked()
            except Exception:
                if old is None:
                    del self.entries[key]
                else:
                    self.entries[key] = old
                raise
            return created

    def get(self, key: str) -> tuple[bool, Any]:
        with self.lock:
            self._purge_locked()
            record = self.entries.get(key)
            return (False, None) if record is None else (True, record["value"])

    def delete(self, key: str) -> bool:
        with self.lock:
            self._purge_locked()
            old = self.entries.pop(key, None)
            if old is None:
                return False
            try:
                self._persist_locked()
            except Exception:
                self.entries[key] = old
                raise
            return True

    def keys(self) -> list[str]:
        with self.lock:
            self._purge_locked()
            return sorted(self.entries)


